/**
 * How the MHPCO settles damage reported against a policy: what it pays out for an
 * incident, and what it keeps back. The office's claim clauses live here -- the
 * deductible it withholds per damaged item, and the clauses that decide how much of
 * a damage it recognises in the first place.
 *
 * <p>Separate from what the office charges: a premium is priced from the price list,
 * the customer's file and the item's risk, while a payout is decided from the damage
 * and the damaged item alone. The two change for different reasons -- so much so that
 * the office's own favour points in opposite directions, rounding a premium up but a
 * payout down.
 */
public final class ClaimSettlement {

    /** The MHPCO keeps this much of every damage event to itself. */
    private static final int DEDUCTIBLE_PER_DAMAGE = 100;

    /** From this enchantment level on, the office recognises only half a damage. */
    private static final int HALVED_REIMBURSEMENT_ENCHANTMENT = 8;

    private ClaimSettlement() {
    }

    /** What the office pays out for everything the incident damaged. */
    public static Settlement forIncident(Policy policy, Incident incident) {
        int payout = incident.damages().stream()
                .mapToInt(damage -> reimbursementFor(damage, damagedItem(policy, damage)))
                .sum();
        return new Settlement(payout);
    }

    /** The insured item a reported damage refers to. */
    private static Item damagedItem(Policy policy, Damage damage) {
        return policy.items().stream()
                .filter(item -> item.type().equals(damage.itemType()))
                .findFirst()
                .orElseThrow();
    }

    /** What the office reimburses for one damaged item, after its deductible. */
    private static int reimbursementFor(Damage damage, Item item) {
        return recognisedDamage(damage, item) - DEDUCTIBLE_PER_DAMAGE;
    }

    /**
     * How much of a damage the office recognises before withholding the deductible:
     * damage to a highly enchanted item is recognised only by half.
     */
    private static int recognisedDamage(Damage damage, Item item) {
        if (item.enchantment() >= HALVED_REIMBURSEMENT_ENCHANTMENT) {
            return damage.amount() / 2;
        }
        return damage.amount();
    }
}
